}{"point":{"id":"source_evidence","title":"Repository Evidence and Navigation","rationale":"Source resolution follows an explicit diagram source binding instead of assuming a project has one repository. Mapping joins resolve selected diagram nodes to captured source ranges, retaining provenance and hashes. Corpus and language-service adapters provide file access and definition lookup, while CodePanel translates these joins into the browsing experience.","sourcePaths":["application/core/source/diagramSource.ts","application/core/source/projectSource.ts","application/core/corpus/corpusAccess.ts","infrastructure/core/corpus/corpus.ts","infrastructure/core/persistence/repositoryRegistry.ts","infrastructure/core/language-services/projectLanguageService.ts","domain/mapping/code-panel/codePanel.ts","src/features/mapping/code-panel/CodePanel.tsx"],"relationships":[{"pointId":"diagrams","label":"resolves source bindings, mappings, and captured evidence","kind":"dependency"},{"pointId":"persistence","label":"reads registered sources and published representations","kind":"dependency"}]},"sources":[{"path":"application/core/source/diagramSource.ts","text":"import { createStoredDiagram } from '../../../domain/core/diagrams/diagramRevisionStore';
import { diagramSource, validateDiagram, type Diagram, type DiagramSourceBinding } from '../../../domain/core/diagrams/diagram';

import { sceneFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
export interface DiagramSourceReference { projectId: string; representationId?: string; revisionId?: string; contentId?: string; sourceId?: string }
/** Resolve a saved diagram/revision, or an unambiguous registered source. Never infer a repository from Project. */
export async function resolveDiagramSource(store: Pick<DiagramRepository,'loadProject'|'projectCatalogs'>, ref: DiagramSourceReference, corpus?: CorpusAccess, liveDiagram?: Diagram) {
  const project = await store.loadProject();
  if (!project || project.id !== ref.projectId) throw new ApplicationError('conflict','Diagram belongs to another project');
  const catalog = ref.representationId ? await store.projectCatalogs.loadRepresentationCatalog(project.id) : undefined;
  let diagram: Diagram | undefined;
  const representation = ref.representationId ? catalog!.representations[ref.representationId] : undefined;
  const revisionId = ref.revisionId ?? representation?.currentRevisionId;
  if (ref.representationId && (!representation || !revisionId || !representation.revisionIds.includes(revisionId))) throw new Error('Unknown diagram revision');
  if (liveDiagram) {
    validateDiagram(liveDiagram);
    if (ref.contentId && liveDiagram.id !== ref.contentId) throw new Error('Live diagram identity does not match selection');
    diagram = liveDiagram;
  } else if (ref.representationId) {
    const scene = sceneFromRevision(catalog!.revisions[revisionId!]);
    const candidates = Object.values(scene.contents).filter(d => ref.contentId ? d.id === ref.contentId : !!d.sourceContext.binding);
    if (candidates.length !== 1) throw new Error('Select an individual diagram with contentId');
    diagram = candidates[0];
  } else {
    const bindings = new Map<string,DiagramSourceBinding>();
    const register = (binding: DiagramSourceBinding) => {
      const old = bindings.get(binding.sourceId);
      if (old && (old.corpus.root !== binding.corpus.root || old.corpus.kind !== binding.corpus.kind || old.repositoryIdentity !== binding.repositoryIdentity)) throw new Error('Conflicting diagram source identity');
      bindings.set(binding.sourceId,binding);
    };
    for (const binding of await store.projectCatalogs.loadDiagramSourceBindings(project.id)) {
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    for (const binding of project.sources ?? []) {
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    if (bindings.size !== 1) throw new Error('A valid diagram sourceId is required; the project has no single repository');
    diagram = createStoredDiagram({id:'source-query',revision:0,ascii:'Source',source:[...bindings.values()][0]}).diagram;
  }
  if (ref.sourceId && diagram.sourceContext.binding?.sourceId !== ref.sourceId) throw new Error('Source does not belong to diagram');
  const query = diagramSource(diagram);
  const binding = () => {
    const result = query.context.binding;
    if (!result) throw new Error('This diagram has no source repository');
    return result;
  };
  return { ...query, diagram, binding,
    readText: (file: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).readDocumentText(source.corpus,file); },
    listFiles: (directory: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).listDirectory(source.corpus,directory); }
  };
}
"},{"path":"application/core/source/projectSource.ts","text":"import { createHash } from 'node:crypto';
import type { SourcePosition } from '../../../domain/core/source/sourceNavigation';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
import { resolveDiagramSource, type DiagramSourceReference } from './diagramSource';
import type { LanguageService } from './languageService';

export class ProjectSourceService {
  constructor(
    private readonly projects: Pick<DiagramRepository, 'loadProject' | 'projectCatalogs'>,
    private readonly corpus: CorpusAccess,
    private readonly language?: LanguageService
  ) { }

  async files(projectId: string | null, directory: string, sourceId?: string) {
    const source = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    return source.listFiles(directory);
  }

  ensureDefinitionsEnabled(): void {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
  }

  async definitions(input: DiagramSourceReference & { path: string; position: SourcePosition; sourceSha256: string }, signal: AbortSignal) {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
    const source = await resolveDiagramSource(this.projects, input, this.corpus);
    return this.language.definitions(source.binding().corpus, input.path, input.position, input.sourceSha256, signal);
  }

  async source(projectId: string | null, sourcePath: string | null, sourceId?: string) {
    if (!sourcePath) throw new ApplicationError('invalid-input', 'Source path is required');
    const resolved = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    const source = await resolved.readText(sourcePath);
    if (source.includes('\0')) throw new ApplicationError('binary-source', 'This is a binary file. The source pane displays text files.');
    return {
      path: sourcePath, startLine: 1, lines: source.split(/\r?\n/),
      sourceSha256: createHash('sha256').update(source).digest('hex'), lspEnabled: Boolean(this.language)
    };
  }
}
